package app

import (
	"context"
	"errors"
	"sync"
	"testing"
	"time"

	runtimepkg "github.com/Antonio7098/ultraplan-go/internal/platform/runtime"
	"github.com/Antonio7098/ultraplan-go/internal/runcontrol"
)

// Reproduction A: durable cancellation (or parent cancel) while a coalesced
// progress omission is pending must not be recorded as persistence_lost.
func TestReproCancellationWithPendingOmissionRecordedAsPersistenceLost(t *testing.T) {
	ctx, cancelParent := context.WithCancel(context.Background())
	defer cancelParent()
	repository, err := runcontrol.OpenSQLite(ctx, t.TempDir(), runcontrol.SQLiteOptions{})
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = repository.Close() })
	owner, err := currentRunOwner()
	if err != nil {
		t.Fatal(err)
	}

	var once sync.Once
	emitted := make(chan struct{})
	spy := &coalesceSpy{onSecondEvent: func() {
		once.Do(func() { close(emitted) })
	}}
	controlled := controlledRuntime{base: spy, repository: repository, owner: owner}

	type outcome struct {
		result runtimepkg.Result
		err    error
	}
	done := make(chan outcome, 1)
	go func() {
		result, runErr := controlled.StartRun(ctx, runtimepkg.Request{
			PromptRef: runtimepkg.PromptReference{OwnerKind: "sprint", Purpose: "execute"},
			OnEvent:   nil,
		})
		done <- outcome{result, runErr}
	}()

	select {
